<?php namespace App\Controllers\Api; use CodeIgniter\RESTful\ResourceController; class TestHaversine extends ResourceController { public function index() { $db = \Config\Database::connect(); $builder = $db->table("drivers"); $pickupLat = -3.40848290; $pickupLng = 119.31244610; $builder->select("drivers.id, ( 6371 * acos( LEAST(1.0, cos(radians(" . $pickupLat . ")) * cos(radians(latitude)) * cos(radians(longitude) - radians(" . $pickupLng . ")) + sin(radians(" . $pickupLat . ")) * sin(radians(latitude))) ) ) AS distance"); $builder->where("is_online", 1); $builder->where("status", "active"); $builder->where("verification_status", "approved"); $builder->having("distance <=", 3); $result = $builder->get()->getResult(); return $this->respond($result); } }
